function findMissing(nums) {
  let i = 0 //@init
  while (i < nums.length) {
    const want = nums[i] - 1 //@want
    if (nums[want] !== nums[i]) [nums[i], nums[want]] = [nums[want], nums[i]] //@swap
    else i++ //@next
  }
  const missing = [] //@scan
  for (let k = 0; k < nums.length; k++) if (nums[k] !== k + 1) missing.push(k + 1) //@check
  return missing //@done
}

